import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {constants} from 'node:fs';
import {lstat, open, opendir, realpath} from 'node:fs/promises';
import {join} from 'node:path';
import {pathToFileURL} from 'node:url';

const builds = {cloud: ['apps/portal/dist'], waitron: ['apps/dashboard/dist', 'apps/server/dist']};
const hash = value => createHash('sha256').update(value).digest('hex');

// An image's source label does not measure the generated bytes that it serves or executes.
export async function measureIntegrationAssets(root, kind) {
  assert.ok(Object.hasOwn(builds, kind), 'integration.assets_kind');
  root = await realpath(root);
  const entries = [];
  let total = 0, visited = 0;
  const visit = async path => {
    assert.ok(++visited <= 10000 && path.split('/').length <= 32, 'integration.assets_count');
    assert.ok(/^[A-Za-z0-9_.@/+\-]+$/.test(path) && !path.split('/').some(part => part.startsWith('.')), 'integration.assets_path');
    const full = join(root, path), info = await lstat(full);
    assert.equal(info.isSymbolicLink(), false, 'integration.assets_symlink');
    assert.equal(await realpath(full), full, 'integration.assets_symlink');
    if (info.isDirectory()) {
      const directory = await opendir(full);
      for await (const item of directory) await visit(path + '/' + item.name);
      return;
    }
    assert.equal(info.isFile(), true, 'integration.assets_file');
    assert.ok(info.size > 0 && info.size <= 64 * 1024 * 1024, 'integration.assets_size');
    total += info.size;
    assert.ok(total <= 256 * 1024 * 1024, 'integration.assets_size');
    const file = await open(full, constants.O_RDONLY | constants.O_NOFOLLOW);
    try {
      assert.equal((await file.stat()).size, info.size, 'integration.assets_changed');
      const digest = createHash('sha256');
      let bytes = 0;
      for await (const part of file.createReadStream({autoClose: false})) {
        bytes += part.length;
        assert.ok(bytes <= info.size, 'integration.assets_changed');
        digest.update(part);
      }
      assert.equal(bytes, info.size, 'integration.assets_changed');
      entries.push({path, bytes, sha256: digest.digest('hex')});
    } finally {await file.close();}
  };
  for (const path of builds[kind]) {
    const before = entries.length;
    await visit(path);
    assert.ok(entries.length > before, 'integration.assets_empty');
  }
  entries.sort((a, b) => a.path < b.path ? -1 : a.path > b.path ? 1 : 0);
  return {kind, files: entries.length, bytes: total, manifestSha256: hash(JSON.stringify(entries)), entries};
}

if (process.argv[1] === '-' || (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href)) {
  try {
    assert.equal(process.argv.length, 3);
    process.stdout.write(JSON.stringify(await measureIntegrationAssets(process.cwd(), process.argv[2])) + '\n');
  } catch {process.stderr.write('Integration assets refused\n'); process.exitCode = 1;}
}
